<?php
require_once __DIR__.'/database.php';
function rangers_investigation_images(array $urls): array { $out=[]; foreach($urls as $url){$url=trim((string)$url);if(preg_match('~^https?://(?:www\.)?imgur\.com/([^/?#]+)~i',$url,$m))$url='https://i.imgur.com/'.$m[1].'.jpg';if(filter_var($url,FILTER_VALIDATE_URL))$out[]=$url;}return array_values(array_unique($out)); }
function rangers_fetch_investigations():array{$out=[];foreach(rangers_firebase_keyed_rows('investigations') as $id=>$x){$updates=array_values(rangers_firebase_get('investigation_updates/'.$id));usort($updates,fn($a,$b)=>strcmp($b['update_datetime']??'',$a['update_datetime']??''));$out[]=['db_id'=>$id,'id'=>strtoupper($x['case_code']??''),'titulo'=>strtoupper($x['title']??''),'fecha_hora'=>str_replace('T',' ',substr($x['case_datetime']??'',0,16)),'agente'=>strtoupper($x['lead_agent_name']??''),'descripcion'=>strtoupper($x['description']??''),'pruebas'=>strtoupper($x['evidence']??''),'imagenes'=>rangers_investigation_images((array)($x['evidence_urls']??[])),'status'=>strtoupper($x['status']??'ABIERTO'),'secciones'=>array_map(fn($u)=>['titulo'=>strtoupper($u['update_title']??''),'fecha_hora'=>str_replace('T',' ',substr($u['update_datetime']??'',0,16)),'agente'=>strtoupper($u['agent_name']??''),'agregado_por'=>strtoupper($u['added_by_name']??''),'descripcion'=>strtoupper($u['description']??''),'pruebas'=>strtoupper($u['evidence']??''),'imagenes'=>rangers_investigation_images((array)($u['image_urls']??[]))],$updates)];}usort($out,fn($a,$b)=>strcmp($b['fecha_hora'],$a['fecha_hora']));return $out;}
function rangers_find_investigation_by_code(string $code):?array{foreach(rangers_fetch_investigations() as $x)if($x['id']===strtoupper(trim($code)))return $x;return null;}
function rangers_create_investigation(array $d,?string $by=null):array{$id=rangers_new_id();$code='INV-'.date('ymdHis').random_int(10,99);rangers_firebase_set('investigations/'.$id,['case_code'=>$code,'title'=>strtoupper(trim($d['titulo']??'')),'case_datetime'=>str_replace('T',' ',trim($d['fecha_hora']??'')),'lead_agent_name'=>strtoupper(trim($d['agente']??$by??'')),'description'=>strtoupper(trim($d['descripcion']??'')),'evidence'=>strtoupper(trim($d['pruebas']??'')),'evidence_urls'=>rangers_investigation_images((array)($d['imagenes']??[])),'status'=>'ABIERTO']);return rangers_find_investigation_by_code($code);}
function rangers_add_investigation_update(string $code,array $d,?string $by=null):?array{$case=rangers_find_investigation_by_code($code);if(!$case)return null;rangers_firebase_set('investigation_updates/'.$case['db_id'].'/'.rangers_new_id(),['update_title'=>strtoupper(trim($d['titulo']??'')),'update_datetime'=>str_replace('T',' ',trim($d['fecha_hora']??'')),'agent_name'=>strtoupper(trim($d['agente']??'')),'added_by_name'=>strtoupper(trim($by??$d['agente']??'')),'description'=>strtoupper(trim($d['descripcion']??'')),'evidence'=>strtoupper(trim($d['pruebas']??'')),'image_urls'=>rangers_investigation_images((array)($d['imagenes']??[]))]);if(!empty($d['status']))rangers_firebase_update('investigations/'.$case['db_id'],['status'=>strtoupper(trim($d['status']))]);return rangers_find_investigation_by_code($code);}
